test("title-becomes-url-slug: a title comes back as a URL-ready slug", () => {
  assert.equal(slugify("Hello World"), "hello-world");
});

test("lower-case: upper-case letters come back as lower case", () => {
  assert.equal(slugify("Hello"), "hello");
});

test("space-becomes-dash: a space between words becomes a dash", () => {
  assert.equal(slugify("hello world"), "hello-world");
});

test("space-run-becomes-one-dash: several spaces in a row become one dash", () => {
  assert.equal(slugify("hello   big world"), "hello-big-world");
});

test("punctuation-dropped: punctuation is removed from the slug", () => {
  assert.equal(slugify("hello!"), "hello");
});

test("accented-letters-dropped: letters outside a-z are removed, not converted", () => {
  assert.equal(slugify("héllo"), "hllo");
});

test("title-becomes-url-slug: a title comes back as a URL-safe slug", () => {
  assert.equal(slugify("Hello World"), "hello-world");
});

test("lower-case: upper-case letters come back in lower case", () => {
  assert.equal(slugify("Hello"), "hello");
});

test("space-becomes-dash: a space between words becomes a dash", () => {
  assert.equal(slugify("big world"), "big-world");
});

test("space-run-single-dash: several spaces in a row become one dash", () => {
  assert.equal(slugify("hello   big"), "hello-big");
});

test("punctuation-dropped: punctuation is removed from the slug", () => {
  assert.equal(slugify("hello!"), "hello");
});

test("accented-letters-dropped: accented letters are removed, not replaced with plain letters", () => {
  assert.equal(slugify("wörld"), "wrld");
});

test('title-becomes-url-slug: "Hello World" becomes "hello-world"', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('lower-case: "Hello" becomes "hello"', () => {
  assert.equal(slugify('Hello'), 'hello');
});

test('spaces-to-single-dash: "hello   big world" becomes "hello-big-world"', () => {
  assert.equal(slugify('hello   big world'), 'hello-big-world');
});

test('drop-other-characters: "héllo, wörld 42!" becomes "hllo-wrld-42"', () => {
  assert.equal(slugify('héllo, wörld 42!'), 'hllo-wrld-42');
});

test("hours-and-minutes-to-seconds: hours and minutes come back as total seconds", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("seconds-unit: a number followed by s is read as seconds", () => {
  assert.equal(parseDuration("45s"), 45);
});

test("minutes-unit: a number followed by m is read as minutes", () => {
  assert.equal(parseDuration("2m"), 120);
});

test("hours-unit: a number followed by h is read as hours", () => {
  assert.equal(parseDuration("1h"), 3600);
});

test("three-parts-summed: hours, minutes and seconds are added up", () => {
  assert.equal(parseDuration("1h30m15s"), 5415);
});

test("bare-number-is-seconds: a number with no unit is read as seconds", () => {
  assert.equal(parseDuration("90"), 90);
});

test("spaces-between-parts: a space between the parts is accepted", () => {
  assert.equal(parseDuration("1h 30m"), 5400);
});

test("upper-case-units: unit letters can be upper case", () => {
  assert.equal(parseDuration("1H30M"), 5400);
});

test("decimal-part: a part can be a decimal number", () => {
  assert.equal(parseDuration("1.5h"), 5400);
});

